public class TicketStock
{
    public int Remaining { get; private set; }
    public TicketStock(int initial)
    {
        if (initial < 0) throw new ArgumentOutOfRangeException(nameof(initial));
        Remaining = initial;
    }
    public bool TryUse()
    {
        if (Remaining == 0) return false;
        Remaining--;
        return true;
    }
}

